{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.spends_growth_scorecard as with cat_spends as ( select date, sum(case when category = \'Shirts\' then spends end)::int as shirts_spends, sum(case when category = \'Trousers\' then spends end)::int as Trousers_spends, sum(case when category = \'T-Shirts\' then spends end)::int as TShirts_spends, sum(case when category = \'Jeans\' then spends end)::int as Jeans_spends, sum(case when category = \'Cargo Pants\' then spends end)::int as Cargo_Pants_spends, sum(spends::int) as cat_spends from snitch_db.maplemonk.category_visibility group by 1 ), campaign_spends as ( SELECT date, sum(case when lower(campaign_name) like \'%video%\' then spend end)::int as videos_spends, sum(case when lower(campaign_name) like \'%catlog%\' then spend end)::int as catalog_spends, sum(case when lower(campaign_name) like \'%product%\' then spend end)::int as product_spends, sum(spend)::int as camp_spends FROM snitch_db.maplemonk.marketing_consolidated_snitch WHERE channel IN (\'Facebook\') group by 1 ), influ_spends as ( SELECT date, ifnull(sum(case when lower(ad_name) like \'%influencer%\' then spend end)::int,0) as influencer_spends, ifnull(sum(case when (ad_name) like \'%PA%\' then spend end)::int,0) as partnership_spends, ifnull(sum(case when (ad_name) like \'%CP%\' then spend end)::int,0) as creator_program_spends, ifnull(sum(case when lower(ad_name) like \'%offer%\' then spend end)::int,0) as offer_spends, ifnull(count(distinct case when lower(campaign_name) like \'%video%\' then ad_name end),0) as total_videos, ifnull(count(distinct case when lower(ad_name) like \'%influencer%\' then ad_name end),0) as influencer_videos, ifnull(count(distinct case when (ad_name) like \'%PA%\' then ad_name end),0) as partnership_videos, ifnull(count(distinct case when (ad_name) like \'%CP%\' then ad_name end),0) as creator_program_videos, ifnull(count(distinct case when lower(ad_name) like \'%offer%\' then ad_name end),0) as offer_videos FROM snitch_db.maplemonk.marketing_consolidated_snitch where channel IN (\'Facebook\') group by 1 ), customer_spend AS ( SELECT TO_DATE(date, \'DD/MM/YYYY\') AS date, REPLACE(new_customer_spend, \',\', \'\')::int AS new_customer_spend, REPLACE(returning_customer_spend, \',\', \'\')::int AS returning_customer_spend FROM snitch_db.maplemonk.GS_GROWTH_SPENDS_SPEND ) select a.*, videos_spends, catalog_spends, product_spends, camp_spends, influencer_spends, partnership_spends, creator_program_spends, offer_spends, total_videos, influencer_videos, partnership_videos, creator_program_videos, offer_videos, new_customer_spend, returning_customer_spend from cat_spends a left join campaign_spends b on a.date = b.date left join influ_spends c on a.date = c.date left join customer_spend d on a.date = d.date ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            